<?php
declare(strict_types=1);
require_once __DIR__ . '/../modules/auth.php';
start_app_session();
if (current_user() !== null && !empty(current_user()['id'])) { header('Location: dashboard.php'); exit; }
if (empty($_SESSION['register_csrf'])) $_SESSION['register_csrf'] = bin2hex(random_bytes(32));
$error=''; $name=''; $workspace=''; $email='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!hash_equals((string)$_SESSION['register_csrf'],(string)($_POST['csrf']??''))){http_response_code(403);exit('Sessão expirada. Atualize a página.');}
    $name=trim((string)($_POST['name']??''));$workspace=trim((string)($_POST['workspace']??''));$email=filter_var(trim((string)($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$password=(string)($_POST['password']??'');$confirm=(string)($_POST['confirm_password']??'');
    if($name===''||$workspace===''||!$email){$error='Preencha nome, nome do espaço e um e-mail válido.';}
    elseif(strlen($password)<12){$error='Crie uma senha com pelo menos 12 caracteres.';}
    elseif($password!==$confirm){$error='As senhas não conferem.';}
    else{try{$user=create_workspace($name,$workspace,(string)$email,$password);session_regenerate_id(true);$_SESSION['affiliate_user']=$user;header('Location: dashboard.php');exit;}catch(DomainException $exception){$error=$exception->getMessage();}catch(Throwable $exception){$error='Não foi possível criar o espaço agora. Confira os dados e tente novamente.';}}
}
function re($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?>
